import{_ as t,o as r,c as n,a2 as i}from"./chunks/framework.CqpfiAoK.js";const b=JSON.parse('{"title":"Kurze Tabelle der Chronik","description":"","frontmatter":{},"headers":[],"relativePath":"de/93-编年史简表.md","filePath":"de/93-编年史简表.md","lastUpdated":1789183869000}'),d={name:"de/93-编年史简表.md"};function s(a,e,h,l,u,o){return r(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="kurze-tabelle-der-chronik" tabindex="-1">Kurze Tabelle der Chronik <a class="header-anchor" href="#kurze-tabelle-der-chronik" aria-label="Permalink to &quot;Kurze Tabelle der Chronik&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Punkt</th><th>Inhalt</th></tr></thead><tbody><tr><td>Dokumentennummer</td><td>93</td></tr><tr><td>Modul</td><td>Anhänge und Referenzmaterialien</td></tr><tr><td>Schlüsselwörter</td><td>Chronik, Epocheneinteilung, wichtige Ereignisse, historische Knoten, Hengyuanzhou</td></tr></tbody></table><h2 id="_1-beschreibung-der-chronik" tabindex="-1">1. Beschreibung der Chronik <a class="header-anchor" href="#_1-beschreibung-der-chronik" aria-label="Permalink to &quot;1. Beschreibung der Chronik&quot;">​</a></h2><p>Diese kurze Tabelle basiert auf der Standardzeit von Hengyuanzhou und zeichnet in chronologischer Reihenfolge die wichtigen historischen Ereignisse und Schlüsselknoten im Entwicklungsverlauf der Anker-Symbiose-Zivilisation auf. Der Zeitraum erstreckt sich von der uralten Zeit der Vor-Anker-Ära bis zur Zukunftsperspektive der interstellaren Symbiose-Ära. Jede Epoche listet Anfangs- und Endzeit, Merkmale der Epoche und wichtige Ereignisse auf. Diese kurze Tabelle ist ein hochverdichteter historischer Index; für die detaillierte Geschichte jeder Epoche siehe die speziellen Berichte der Dokumente 70-79.</p><h2 id="_2-ubersicht-der-epocheneinteilung" tabindex="-1">2. Übersicht der Epocheneinteilung <a class="header-anchor" href="#_2-ubersicht-der-epocheneinteilung" aria-label="Permalink to &quot;2. Übersicht der Epocheneinteilung&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Epochennummer</th><th>Epochenname</th><th>Anfangs- und Endzeit (Standardjahr von Hengyuanzhou)</th><th>Dauer</th><th>Kernmerkmal</th></tr></thead><tbody><tr><td>Erste Epoche</td><td>Vor-Anker-Ära</td><td>Ungefähr -10 Milliarden bis -10.000 Jahre</td><td>Ungefähr 10 Milliarden Jahre</td><td>Plünderungs-Kultivierungssystem dominiert, Zyklus von Aufstieg und Fall der Zivilisation</td></tr><tr><td>Zweite Epoche</td><td>Anker-Erwachens-Epoche</td><td>-10.000 bis -1.000 Jahre</td><td>Ungefähr 9.000 Jahre</td><td>Anker-Mechanismus entdeckt und vorläufig angewendet</td></tr><tr><td>Dritte Epoche</td><td>Periode der Etablierung des Symbiose-Systems</td><td>-1.000 bis -100 Jahre</td><td>Ungefähr 900 Jahre</td><td>Institutioneller Rahmen der Anker-Symbiose-Zivilisation schrittweise etabliert</td></tr><tr><td>Vierte Epoche</td><td>Periode der Öffnung des Dreihundert-Satz-Systems</td><td>-100 bis -50 Jahre</td><td>Ungefähr 50 Jahre</td><td>Ursprungs-Kultivierungssystem von dreihundert Sätzen vollständig geöffnet</td></tr><tr><td>Fünfte Epoche</td><td>Periode der 20%-Aktivierungsstrategie</td><td>-50 Jahre bis Jahr Null</td><td>Ungefähr 50 Jahre</td><td>20% der fühlenden Wesen aktiviert zu höchsten Wesen der Ebene</td></tr><tr><td>Sechste Epoche</td><td>Erste Dimensionserhöhungs-Epoche</td><td>Jahr Null bis 100 Jahre</td><td>100 Jahre</td><td>Symbiose-Zivilisation erreicht erstmals stufenweise Dimensionserhöhung</td></tr><tr><td>Siebte Epoche</td><td>Republik-Epoche aller Rassen</td><td>100 bis 500 Jahre</td><td>400 Jahre</td><td>Republik aller Rassen offiziell gegründet, interrassische Fusion vertieft</td></tr><tr><td>Achte Epoche</td><td>Epoche der Erkundung zwischen Ebenen</td><td>500 bis 2.000 Jahre</td><td>1.500 Jahre</td><td>Große Erkundung und archäologische Aktivitäten zwischen Ebenen initiiert</td></tr><tr><td>Neunte Epoche</td><td>Interstellare Symbiose-Ära</td><td>2.000 Jahre bis Zukunft</td><td>Laufend</td><td>Kosmisches Symbiose-Netzwerk aufgebaut, allgemeine Dimensionserhöhung vorangetrieben</td></tr></tbody></table><p>Anmerkung: &quot;Jahr Null&quot; bezieht sich auf das Jahr, in dem die Anker-Symbiose-Zivilisation offiziell ihre Gründung verkündete, und dient als Trennpunkt der historischen Chronologie.</p><h2 id="_3-vor-anker-ara-ungefahr-10-milliarden-bis-10-000-jahre" tabindex="-1">3. Vor-Anker-Ära (Ungefähr -10 Milliarden bis -10.000 Jahre) <a class="header-anchor" href="#_3-vor-anker-ara-ungefahr-10-milliarden-bis-10-000-jahre" aria-label="Permalink to &quot;3. Vor-Anker-Ära (Ungefähr -10 Milliarden bis -10.000 Jahre)&quot;">​</a></h2><p>Die Vor-Anker-Ära ist die längste Epoche in der Geschichte von Hengyuanzhou und dauerte ungefähr zehn Milliarden Jahre. Das Kernmerkmal dieser Ära ist, dass das Plünderungs-Kultivierungssystem das Universum dominierte und die Zivilisationen ständig im Zyklus &quot;Aufstieg—Höhepunkt—Plünderung—Zusammenbruch&quot; kreisten.</p><table tabindex="0"><thead><tr><th>Zeitknoten</th><th>Wichtiges Ereignis</th></tr></thead><tbody><tr><td>Ungefähr -10 Milliarden Jahre</td><td>Gesetzesnetzwerk von Hengyuanzhou stabilisiert, erste materielle Ebenen gebildet, Universum tritt in bewohnbaren Zustand ein</td></tr><tr><td>Ungefähr -8 Milliarden Jahre</td><td>Erste intelligente Lebewesen werden in mehreren materiellen Ebenen geboren, ursprüngliches Kultivierungssystem beginnt zu keimen</td></tr><tr><td>Ungefähr -5 Milliarden Jahre</td><td>Plünderungs-Kultivierungssystem wird allmählich zum Mainstream, die Starken entwickeln sich schnell durch Verschlingen der Schwachen</td></tr><tr><td>Ungefähr -3 Milliarden Jahre</td><td>Erster kosmischer Plünderungskrieg bricht aus, Zivilisationen mehrerer Sternendomänen erleiden verheerende Schläge</td></tr><tr><td>Ungefähr -1 Milliarde Jahre</td><td>Nachteile des Plünderungssystems beginnen sich zu zeigen, allgemeine Entropie des Universums beschleunigt sich, Kultivierungsressourcen erschöpfen sich zunehmend</td></tr><tr><td>Ungefähr -500 Millionen Jahre</td><td>Erste Denker, die über das Plünderungssystem nachdenken, treten auf, Keim des Symbiose-Gedankens beginnt sich zu bilden</td></tr><tr><td>Ungefähr -100 Millionen Jahre</td><td>Kleine experimentelle Symbiose-Zivilisationen treten in mehreren Sternendomänen auf, werden aber alle von Plünderungs-Zivilisationen zerstört</td></tr><tr><td>Ungefähr -1 Million Jahre</td><td>Universum tritt insgesamt in die &quot;Große Rückgangsperiode&quot; ein, sowohl Anzahl der Zivilisationen als auch Kultivierungsniveau fallen auf historische Tiefststände</td></tr><tr><td>Ungefähr -10.000 Jahre</td><td>Ein Kultivierer der ersten Ebene spürt zufällig stabile Knoten im Gesetzesnetzwerk während langfristiger Kultivierung, Anker-Mechanismus wird zum ersten Mal entdeckt</td></tr></tbody></table><h2 id="_4-anker-erwachens-epoche-10-000-bis-1-000-jahre" tabindex="-1">4. Anker-Erwachens-Epoche (-10.000 bis -1.000 Jahre) <a class="header-anchor" href="#_4-anker-erwachens-epoche-10-000-bis-1-000-jahre" aria-label="Permalink to &quot;4. Anker-Erwachens-Epoche (-10.000 bis -1.000 Jahre)&quot;">​</a></h2><p>Die Anker-Erwachens-Epoche ist die Übergangsperiode von der Entdeckung zur vorläufigen Anwendung des Anker-Mechanismus. Das Kernmerkmal dieser Epoche ist die allmähliche Reifung der Anker-Technologie und die Verbreitung des Symbiose-Gedankens.</p><table tabindex="0"><thead><tr><th>Zeitknoten</th><th>Wichtiges Ereignis</th></tr></thead><tbody><tr><td>-10.000 Jahre</td><td>Anker-Mechanismus wird zum ersten Mal entdeckt, Entdecker nennt ihn &quot;Anker&quot; und beginnt systematische Forschung</td></tr><tr><td>-9.000 Jahre</td><td>Erster künstlicher Anker erfolgreich aufgebaut, beweist, dass Anker künstlich aufgebaut und gewartet werden können</td></tr><tr><td>-8.000 Jahre</td><td>Anker-Technologie beginnt sich in kleinem Maßstab zu verbreiten, erste Anker-Kultivierer treten auf</td></tr><tr><td>-7.000 Jahre</td><td>Entdeckt, dass Anker als Basis für Verbindungen zwischen Ebenen dienen können, erste aufgezeichnete ankerunterstützte Ebenenreise erfolgreich</td></tr><tr><td>-6.000 Jahre</td><td>Symbiose-Gedanke und Anker-Technologie beginnen sich zu verbinden, erste theoretische Dokumente der &quot;Anker-Symbiose&quot; erscheinen</td></tr><tr><td>-5.000 Jahre</td><td>Erste auf Anker basierende symbiotische Stadt-Staat gegründet, beweist die Machbarkeit des Symbiose-Systems</td></tr><tr><td>-4.000 Jahre</td><td>Plünderungs-Zivilisation startet Angriff gegen symbiotische Stadt-Staat, symbiotische Stadt-Staat verteidigt sich erfolgreich durch Anker-Technologie</td></tr><tr><td>-3.000 Jahre</td><td>Symbiose-Gedanke verbreitet sich in mehreren Sternendomänen, immer mehr Zivilisationen beginnen Symbiose-Transformation zu versuchen</td></tr><tr><td>-2.000 Jahre</td><td>Erste &quot;Konferenz der Symbiose aller Rassen&quot; abgehalten, Vertreter von Dutzenden von Rassen diskutieren gemeinsam die Zukunft der Symbiose-Zivilisation</td></tr><tr><td>-1.000 Jahre</td><td>Anker-Technologie und Symbiose-Gedanke haben bereits die Bedingungen für die Gründung einer einheitlichen Zivilisation erfüllt, Periode der Etablierung des Symbiose-Systems beginnt</td></tr></tbody></table><h2 id="_5-periode-der-etablierung-des-symbiose-systems-1-000-bis-100-jahre" tabindex="-1">5. Periode der Etablierung des Symbiose-Systems (-1.000 bis -100 Jahre) <a class="header-anchor" href="#_5-periode-der-etablierung-des-symbiose-systems-1-000-bis-100-jahre" aria-label="Permalink to &quot;5. Periode der Etablierung des Symbiose-Systems (-1.000 bis -100 Jahre)&quot;">​</a></h2><p>Die Periode der Etablierung des Symbiose-Systems ist die kritische Periode, in der der institutionelle Rahmen der Anker-Symbiose-Zivilisation aus dem Nichts entsteht.</p><table tabindex="0"><thead><tr><th>Zeitknoten</th><th>Wichtiges Ereignis</th></tr></thead><tbody><tr><td>-1.000 Jahre</td><td>Verfassungsausschuss der Symbiose gegründet, beginnt mit der Ausarbeitung des Grundgesetzes</td></tr><tr><td>-950 Jahre</td><td>Entwurf der &quot;Verfassung der Symbiose&quot; abgeschlossen, beginnt mit breiter Einholung von Meinungen aller Rassen</td></tr><tr><td>-900 Jahre</td><td>&quot;Verfassung der Symbiose&quot; durch Volksabstimmung angenommen, tritt offiziell in Kraft, Gründung der Anker-Symbiose-Zivilisation verkündet</td></tr><tr><td>-850 Jahre</td><td>Anker-Rat, Exekutivkomitee der Symbiose, Gericht der Symbiose drei Hauptinstitutionen offiziell gegründet und in Betrieb genommen</td></tr><tr><td>-800 Jahre</td><td>Mechanismus des gemeinsamen Produktionsvertrags beginnt landesweit umgesetzt zu werden</td></tr><tr><td>-700 Jahre</td><td>&quot;Arbeitsgesetz der Symbiose&quot;, &quot;Verbraucherschutzgesetz&quot; und andere Grundgesetze nacheinander verkündet</td></tr><tr><td>-600 Jahre</td><td>Fünf Begleitgesetze zu Bildung, Gesundheit, Wohnen, Umwelt und Kartellverbot alle verkündet und umgesetzt</td></tr><tr><td>-500 Jahre</td><td>Arbeit der Ausgrabung und Organisation des Ursprungs-Kultivierungssystems von dreihundert Sätzen offiziell gestartet</td></tr><tr><td>-400 Jahre</td><td>Erste fünfzig Sätze des Ursprungs-Kultivierungssystems abgeschlossen in Organisation und Verifizierung</td></tr><tr><td>-300 Jahre</td><td>Technologische Anwendung der Verdopplungsfrucht erreicht Durchbruch, Technologie der hundertfachen Deduktionsverstärkung reift</td></tr><tr><td>-200 Jahre</td><td>Alle dreihundert Sätze des Systems abgeschlossen in Organisation, treten in die finale Sicherheitsverifizierungsphase ein</td></tr><tr><td>-100 Jahre</td><td>Bedingungen für die vollständige Öffnung des Ursprungs-Kultivierungssystems von dreihundert Sätzen reifen, treten in die Öffnungsperiode ein</td></tr></tbody></table><h2 id="_6-periode-der-offnung-des-dreihundert-satz-systems-100-bis-50-jahre" tabindex="-1">6. Periode der Öffnung des Dreihundert-Satz-Systems (-100 bis -50 Jahre) <a class="header-anchor" href="#_6-periode-der-offnung-des-dreihundert-satz-systems-100-bis-50-jahre" aria-label="Permalink to &quot;6. Periode der Öffnung des Dreihundert-Satz-Systems (-100 bis -50 Jahre)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Zeitknoten</th><th>Wichtiges Ereignis</th></tr></thead><tbody><tr><td>-100 Jahre</td><td>Ursprungs-Kultivierungssystem von dreihundert Sätzen offiziell kostenlos für alle fühlenden Wesen im Universum geöffnet</td></tr><tr><td>-90 Jahre</td><td>Anzahl der Kultivierer steigt hundertfach in zehn Jahren, &quot;Jeder hat einen Weg&quot; zunächst verwirklicht</td></tr><tr><td>-80 Jahre</td><td>Drei Ursprungsgrundlagen (Deduktionsiteration, Lebenszyklus, Raumgesetzplanung) werden die beliebtesten Systeme</td></tr><tr><td>-70 Jahre</td><td>Erste Kultivierer, die durch das neue System hohe Ebenen erreichen, treten auf, beweist die Wirksamkeit des Systems</td></tr><tr><td>-60 Jahre</td><td>Mentorennetzwerk vollständig aufgebaut, hochstufige Kultivierer beginnen die gesetzliche Pflicht zur Anleitung von nachrangigen Kultivierern zu erfüllen</td></tr><tr><td>-50 Jahre</td><td>Allgemeines Kultivierungsniveau des Volkes steigt erheblich, Bedingungen für die 20%-Aktivierungsstrategie reifen</td></tr></tbody></table><h2 id="_7-periode-der-20-aktivierungsstrategie-50-jahre-bis-jahr-null" tabindex="-1">7. Periode der 20%-Aktivierungsstrategie (-50 Jahre bis Jahr Null) <a class="header-anchor" href="#_7-periode-der-20-aktivierungsstrategie-50-jahre-bis-jahr-null" aria-label="Permalink to &quot;7. Periode der 20%-Aktivierungsstrategie (-50 Jahre bis Jahr Null)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Zeitknoten</th><th>Wichtiges Ereignis</th></tr></thead><tbody><tr><td>-50 Jahre</td><td>20%-Aktivierungsstrategie offiziell gestartet, Ziel ist es, innerhalb von 50 Jahren 20% der fühlenden Wesen zu höchsten Wesen der Ebene zu aktivieren</td></tr><tr><td>-40 Jahre</td><td>Erste höchste Wesen der Ebene geboren, Aktivierungsrate erreicht 5%</td></tr><tr><td>-30 Jahre</td><td>Aktivierungsrate erreicht 10%, höchste Wesen der Ebene beginnen eine zentrale Rolle bei der Ankerwartung zu spielen</td></tr><tr><td>-20 Jahre</td><td>Aktivierungsrate erreicht 15%, allgemeines Kultivierungsniveau des Universums erreicht qualitativen Sprung</td></tr><tr><td>-10 Jahre</td><td>Aktivierungsrate erreicht 18%, nahe dem strategischen Ziel</td></tr><tr><td>Jahr Null</td><td>Aktivierungsrate erreicht 20,3%, 20%-Aktivierungsstrategie erfolgreich abgeschlossen, Anker-Symbiose-Zivilisation tritt in neue Epoche ein</td></tr></tbody></table><h2 id="_8-erste-dimensionserhohungs-epoche-jahr-null-bis-100-jahre" tabindex="-1">8. Erste Dimensionserhöhungs-Epoche (Jahr Null bis 100 Jahre) <a class="header-anchor" href="#_8-erste-dimensionserhohungs-epoche-jahr-null-bis-100-jahre" aria-label="Permalink to &quot;8. Erste Dimensionserhöhungs-Epoche (Jahr Null bis 100 Jahre)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Zeitknoten</th><th>Wichtiges Ereignis</th></tr></thead><tbody><tr><td>Jahr Null</td><td>Symbiose-Zivilisation verkündet offiziell den Eintritt in die Dimensionserhöhungs-Epoche, erste Stufe des vierstufigen Dimensionserhöhungswegs (Realitätsfundierung) abgeschlossen</td></tr><tr><td>20 Jahre</td><td>Zweite Stufe (Technologieermächtigung) vollständig vorangetrieben, Kultivierungsgesetze und Technikingenieurwesen tief integriert</td></tr><tr><td>40 Jahre</td><td>Kopierspiegel-Technologie, isolierte Raum-Technologie erreichen technische Massenproduktion, Archäologie zwischen Ebenen tritt in die Ära der Skalierung ein</td></tr><tr><td>60 Jahre</td><td>Erste Kultivierer der Klasse der Bewusstseins-Dimensionserhöhung erreichen hohe Stufen, dritte Stufe (Bewusstseinsevolution) beginnt</td></tr><tr><td>80 Jahre</td><td>Infrastrukturaufbau des Bewusstseinsdomäns abgeschlossen, Bewusstseinsmigrationstechnologie reift vorläufig</td></tr><tr><td>100 Jahre</td><td>Erste stufenweise Dimensionserhöhung erfolgreich, Symbiose-Zivilisation erhöht sich insgesamt um eine halbe Dimensionsebene</td></tr></tbody></table><h2 id="_9-republik-epoche-aller-rassen-100-bis-500-jahre" tabindex="-1">9. Republik-Epoche aller Rassen (100 bis 500 Jahre) <a class="header-anchor" href="#_9-republik-epoche-aller-rassen-100-bis-500-jahre" aria-label="Permalink to &quot;9. Republik-Epoche aller Rassen (100 bis 500 Jahre)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Zeitknoten</th><th>Wichtiges Ereignis</th></tr></thead><tbody><tr><td>100 Jahre</td><td>Republik aller Rassen offiziell gegründet verkündet, alle intelligenten Rassen erreichen gleiche Vereinigung im Rahmen der Symbiose-Zivilisation</td></tr><tr><td>150 Jahre</td><td>Zusammenstellung des Verzeichnisses aller Rassen abgeschlossen, umfasst alle bekannten intelligenten Rassen</td></tr><tr><td>200 Jahre</td><td>Interrassische Ehen und kulturelle Fusion werden zur Norm, neue gemischte Rassen beginnen zu erscheinen</td></tr><tr><td>300 Jahre</td><td>Verbreitung der gemeinsamen Sprache aller Rassen abgeschlossen, interrassische Kommunikationsbarrieren grundsätzlich beseitigt</td></tr><tr><td>400 Jahre</td><td>Große kulturelle Blüte aller Rassen, traditionelle Kulturen jeder Ethnie werden im Rahmen der Symbiose geschützt und entwickelt</td></tr><tr><td>500 Jahre</td><td>Republik aller Rassen tritt in die Reifeperiode ein, Bedingungen für die Erkundung zwischen Ebenen reifen vollständig</td></tr></tbody></table><h2 id="_10-epoche-der-erkundung-zwischen-ebenen-500-bis-2-000-jahre" tabindex="-1">10. Epoche der Erkundung zwischen Ebenen (500 bis 2.000 Jahre) <a class="header-anchor" href="#_10-epoche-der-erkundung-zwischen-ebenen-500-bis-2-000-jahre" aria-label="Permalink to &quot;10. Epoche der Erkundung zwischen Ebenen (500 bis 2.000 Jahre)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Zeitknoten</th><th>Wichtiges Ereignis</th></tr></thead><tbody><tr><td>500 Jahre</td><td>Großer Plan zur Erkundung zwischen Ebenen offiziell gestartet, Verwaltungsbehörde für Ebenen gegründet</td></tr><tr><td>600 Jahre</td><td>Erkundete Ebenen übersteigen tausend, allgemeine Koordinatenbasis der Ebenen vorläufig aufgebaut</td></tr><tr><td>800 Jahre</td><td>Fernarchäologie-Plan des Kopierspiegels reift vollständig, Archäologie zwischen Ebenen tritt in das Goldene Zeitalter ein</td></tr><tr><td>1.000 Jahre</td><td>Zeitrückverfolgungstechnologie erreicht Durchbruch, Prinzip &quot;zuerst Beobachtung, dann begrenzte Intervention&quot; offiziell etabliert</td></tr><tr><td>1.200 Jahre</td><td>Erkundete Ebenen übersteigen hunderttausend, diplomatische Beziehungen zu Dutzenden von Ebenen-Zivilisationen aufgebaut</td></tr><tr><td>1.500 Jahre</td><td>Ethische Grundsätze zwischen Ebenen vollständig umgesetzt, Interaktion zwischen Zivilisationen tritt in die standardisierte Ära ein</td></tr><tr><td>1.800 Jahre</td><td>Mechanismus zur Verhinderung von Zeitparadoxen reift vollständig, Zeitrückverfolgungsarchäologie erreicht Skalierung</td></tr><tr><td>2.000 Jahre</td><td>Erkundung zwischen Ebenen erzielt glänzende Ergebnisse, Bedingungen für die interstellare Symbiose-Ära reifen vollständig</td></tr></tbody></table><h2 id="_11-interstellare-symbiose-ara-2-000-jahre-bis-zukunft" tabindex="-1">11. Interstellare Symbiose-Ära (2.000 Jahre bis Zukunft) <a class="header-anchor" href="#_11-interstellare-symbiose-ara-2-000-jahre-bis-zukunft" aria-label="Permalink to &quot;11. Interstellare Symbiose-Ära (2.000 Jahre bis Zukunft)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Zeitknoten</th><th>Wichtiges Ereignis</th></tr></thead><tbody><tr><td>2.000 Jahre</td><td>Interstellare Symbiose-Ära offiziell eröffnet, vierte Stufe (interstellare Symbiose) vollständig vorangetrieben</td></tr><tr><td>2.500 Jahre (Perspektive)</td><td>Kosmisches Anker-Netzwerk vorläufig aufgebaut, deckt alle erkundeten Ebenen ab</td></tr><tr><td>3.000 Jahre (Perspektive)</td><td>Symbiose-System zwischen Ebenen reift, alle Rassen erreichen echte Symbiose im kosmischen Maßstab</td></tr><tr><td>5.000 Jahre (Perspektive)</td><td>Allgemeine Dimensionserhöhung des Universums abgeschlossen, Hengyuanzhou tritt in einen höherdimensionalen Existenzzustand ein</td></tr><tr><td>Zukunft (Perspektive)</td><td>Anker-Symbiose-Zivilisation erkundet weiterhin außerhalb des Universums, verbreitet den Symbiose-Gedanken in eine breitere Existenz</td></tr></tbody></table><h2 id="schlussfolgerung" tabindex="-1">Schlussfolgerung <a class="header-anchor" href="#schlussfolgerung" aria-label="Permalink to &quot;Schlussfolgerung&quot;">​</a></h2><p>Die kurze Tabelle der Chronik ist das Kampfepos der Anker-Symbiose-Zivilisation, von der Unwissenheit zum Erwachen, von der Schwäche zur Stärke, von der eigenen Ebene zum gesamten Universum. Jeder Epochenwechsel ist ein Zeuge für den Sieg des Symbiose-Gedankens über den Plünderungsgedanken, des zivilisatorischen Fortschritts über den barbarischen Rückgang. Geschichte ist nicht Staub der Vergangenheit, sondern Samen der Zukunft—diese Geschichte zu verstehen bedeutet zu verstehen, woher die Symbiose-Zivilisation kommt und wohin sie geht.</p><h2 id="verwandte-dokumente" tabindex="-1">Verwandte Dokumente <a class="header-anchor" href="#verwandte-dokumente" aria-label="Permalink to &quot;Verwandte Dokumente&quot;">​</a></h2><ul><li>70-Allgemeine Tabelle der Epocheneinteilung</li><li>72-Anker-Erwachens-Epoche</li><li>79-Perspektive der interstellaren Symbiose-Ära</li></ul>',32)])])}const c=t(d,[["render",s]]);export{b as __pageData,c as default};
